let StoreTypeCfg ={
    "2":"stickyWild",
    "3":"randomWild",
    "4":"roamingWild",
    "5":"removeSymbol",
    "6":"extraBonus",
    "7":"multBonus",
}

cc.Class({
    extends: cc.Component,

    properties:{
        wild_game_title_node:cc.Node,
        wild_node:cc.Node,
        spine_appear:sp.Skeleton,
        spine_symbol:sp.Skeleton,
        _symbols:[],
        _stickyIdxs:[], // 保存sticky wild idx 数据
        _isEnterWild:false, // 是否进入了wild游戏
    },

    onLoad() {
        this.wild_node.active = false;
        this.spine_appear.node.active = false;
        this.spine_symbol.node.active = false;
    },

    /////////////////random Wild 相关///////////////
    /**
     * 显示随机wild
     * @param idxs
     * @returns {Promise<void>}
     */
    async showRandomWild() {
        SlotsFacade.slots.showMask();
        await SlotsFacade.delayTime(0.2);
        this.wild_node.active = true;
        let storeInfo = SlotsFacade.dm.energyData;
        let wildIdxs = storeInfo.freeInfo.randomWild.idxs.concat();
        // 生成随机wild symbol
        for(let i=0; i<wildIdxs.length; i++) {
            let symbol = this.genAWildSymbol(wildIdxs[i]);
            symbol.getComponent(sp.Skeleton).setAnimation(0,"animation3", false);
            let appearNode = cc.instantiate(this.spine_appear.node);
            appearNode.active = true;
            appearNode.parent = this.wild_node;
            appearNode.position = symbol.position;
            let appearSpine = appearNode.getComponent(sp.Skeleton);
            appearSpine.setAnimation(0, "animation", false);
            appearSpine.setCompleteListener(()=>{
                appearSpine.setCompleteListener(null);
                appearNode.removeFromParent(true);
            });
            this._symbols.push(symbol);
            SlotsFacade.soundMgr.playEffect("symbol_wild");
            await SlotsFacade.delayTime(0.5);
        }
        SlotsFacade.slots.hideMask();
    },

    /////////////////StickyWild 相关///////////////
    _initStickyWild() {
        let energyData = SlotsFacade.dm.energyData;
        if(!energyData.freeInfo || !energyData.freeInfo.stickyWild) {
            return;
        }
        let idxs = energyData.freeInfo.stickyWild;
        this.wild_node.active = true;
        for(let i=0; i<idxs.length; i++) {
            if(this._stickyIdxs.includes(idxs[i])) {
                continue;
            }
            let symbol = this.genAWildSymbol(idxs[i]);
            symbol.getComponent(sp.Skeleton).setAnimation(0,"animation3", false);
            this._symbols.push(symbol);
            this._stickyIdxs.push(idxs[i]);
        }
    },
    /**
     * 显示sticky Wild
     * @private
     */
    _showStickyWild() {
        this.wild_node.active = true;
    },

    /////////////////extra bonus///////////////

    /////////////////roaming bonus///////////////
    /**
     * 添加roaming wild
     * @private
     */
    _addRoamingWild() {
        let energyData = SlotsFacade.dm.energyData;
        if(!energyData.freeInfo || !energyData.freeInfo.roamingWild) {
            return;
        }
        let spinData = SlotsFacade.dm.getSpinData();
        if(!spinData) {
            return;
        }
        let cards = SlotsFacade.dm.getSpinData().resultCards;
        let idxs = [];
        for(let i=0; i<cards.length; i++) {
            if(SlotsFacade.dm.getGameCfg().wildId == cards[i]) {
                idxs.push(i+1);
            }
        }
        if(idxs.length < 1) {
            return;
        }
        this.wild_node.active = true;
        for(let i=0; i<idxs.length; i++) {
            let symbol = this.genAWildSymbol(idxs[i]);
            symbol.getComponent(sp.Skeleton).setAnimation(0,"animation3", false);
            symbol.preIdx = idxs[i];
            this._symbols.push(symbol);
        }
    },

    /**
     * 移动wild
     * @private
     */
    async _moveRoamingWild() {
        if(this._symbols.length < 1) {
            return;
        }
        let energyData = SlotsFacade.dm.energyData;
        if(!energyData.freeInfo || !energyData.freeInfo.roamingWild) {
            return;
        }
        let roamingWild = energyData.freeInfo.roamingWild;
        for(let s of this._symbols) {
            let index = roamingWild.preWilds.indexOf(s.preIdx);
            if(index == -1) {
                s.removeFromParent(true);
                continue;
            }
            let idx = roamingWild.currWilds[index];
            let spine = s.getComponent(sp.Skeleton);
            let pos = null;
            if(idx > 0) {
                pos = SlotsFacade.slots.getIdxGlobalPos(idx);
                pos = this.wild_node.convertToNodeSpaceAR(pos);
            }else {
                pos = cc.v2(s.x-120, s.y);
            }
            let needRemove = false;
            if(idx < 1) {
                needRemove = true;
            }else {
                if(!roamingWild.cols.includes(SlotsFacade.slots.transferIdx(idx).col+1)) {
                    needRemove = true;
                }
            }
            if(needRemove) {
                spine.setAnimation(0, "animation2", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.removeFromParent(true);
                });
            }else {
                spine.setAnimation(0, "animation", false);
            }
            cc.tween(s)
                .to(1.5, {x:pos.x, y:pos.y})
                .start();
        }
        await SlotsFacade.delayTime(3)
    },

    /////////////////标题控制相关///////////////
    _showTitle() {
        let storeFreeInfo = SlotsFacade.dm.energyData.freeInfo;
        if(!storeFreeInfo) {
            return;
        }
        let storeTypes = [];
        for(let i=2; i<=7; i++) {
            let contain = storeFreeInfo.hasOwnProperty(StoreTypeCfg[i.toString()]);
            if(contain) {
                storeTypes.push(i);
            }
        }
        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(storeTypes.length>0) {
            this.wild_game_title_node.active = true;
            cc.find("store_types1", this.wild_game_title_node).active = storeTypes.length == 1;
            cc.find("store_types2", this.wild_game_title_node).active = storeTypes.length == 2;
            cc.find("bg", this.wild_game_title_node).getComponent("ImgSwitchCmp").setIndex(storeTypes.length-1);
            cc.find("bg/spine", this.wild_game_title_node).getComponent(sp.Skeleton).setAnimation(0, `animation${storeTypes.length}`, true);
            for(let i=2; i<=7; i++) {
                let node = cc.find(`store_types${storeTypes.length}/type${i}`, this.wild_game_title_node);
                if(storeTypes.includes(i)) {
                    node.active = true;
                    if(i == StoreItemType.removeSymbol) {
                        let childArr = node.children;
                        for(let n of childArr) {
                            if(n.name == "title") {
                                continue;
                            }
                            n.active = storeFreeInfo.removeSymbol.includes(parseInt(n.name));
                        }
                    }else if(i == StoreItemType.extraBonus) {
                        node.getChildByName("title").getComponent("ImgSwitchCmp").setIndex(storeFreeInfo.extraBonus.length-1);
                    }
                }else {
                    node.active = false;
                }
            }
        } else {
            this.wild_game_title_node.active = false;
        }
    },
    _hideTile() {
        this.wild_game_title_node.active = false;
    },
    /////////////////wild game 流程相关///////////////
    /**
     * 生成一个wild图标
     * @param {*} idx
     */
    genAWildSymbol(idx) {
        let node = cc.instantiate(this.spine_symbol.node);
        node.parent = this.wild_node;
        node.active = true;
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return node;
    },

    /**
     * 进入wild game
     * @returns {Promise<void>}
     */
    async enterWildGame() {
        this._isEnterWild = true;
        this._showTitle();
        this._initStickyWild();
    },

    /**
     * 退出wild game
     * @returns {Promise<void>}
     */
    async exitWildGame() {
        this.removeWild();
        this._hideTile();
        this._isEnterWild = false;
    },

    /**
     * 移除wild
     */
    removeWild() {
        this._symbols = [];
        this._stickyIdxs = [];
        this.wild_node.active = false;
        this.wild_node.removeAllChildren();
    },

    /**
     * 隐藏wild
     */
    hideWild() {
        this.wild_node.active = false;
    },

    /**
     * 判断 是否有 store 类型
     */
    hasStoreType(storeType) {
        let storeFreeInfo = SlotsFacade.dm.energyData.freeInfo;
        if(!storeFreeInfo) {
            return false;
        }
        return storeFreeInfo.hasOwnProperty(StoreTypeCfg[storeType.toString()]);
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async startMove() {
        let storeInfo = SlotsFacade.dm.energyData;
        if(storeInfo.state != 1) {
            return false;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }
        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
            this._showStickyWild();
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
        }else if(this.hasStoreType(StoreItemType.roamingWilds)) {
            this._addRoamingWild();
        }
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        let mapInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(mapInfo.state != 1) {
            return;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }

        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
            await this.showRandomWild();
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
            // await SlotsFacade.character.playDiamondAni();
        }else if(this.hasStoreType(StoreItemType.roamingWilds)) {
            await this._moveRoamingWild();
        }
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        let storeInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(storeInfo.state != 1) {
            return;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }

        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
            await this.removeWild();
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
            await this.hideWild();
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
            await this.hideWild();
        }else if(this.hasStoreType(StoreItemType.roamingWilds)) {
            await this.removeWild();
        }
    }
 })