
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        label:cc.Label,                     // 水滴数量文本
        icon:cc.Node,                       // 水滴icon
        spineArrive:sp.Skeleton,            // 收集水滴到达时特效
        spineLock:sp.Skeleton,              // 枷锁解锁效果spine
        traceParticle:cc.ParticleSystem,    // 收集粒子
        tips:cc.Node,
        isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._initListener();
    },

    start() {
        this.scheduleOnce(()=>{
            this._init();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.node.on("click", ()=>{
            // 如果在免费中 返回
            if(SlotsFacade.dm.hasFree()) {
                return;
            }
            // 如果spin不可点击 返回
            if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
                return;
            }
            // 自动旋转模式 返回
            if(SlotsFacade.dm.GetAutoModelTime() > 0) {
                return;
            }
            if(this.isOpen) {
                this._openStore();
            }else{
                this._openCollect();
            }
        }, this);
    },

    _init() {
        this.setCnt(SlotsFacade.dm.energyData.gemCnt);
        this.showCollect(true);
    },

    _openStore() {
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.storeGame.open(()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 显示收集界面
     * @param isInit 是否是初始化
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(isInit) {
                this.spineLock.setAnimation(0, "animation1", true);
            }else {
                if(!this.isOpen) {
                    SlotsFacade.soundMgr.playEffect("map_unlock");
                    this.spineLock.setAnimation(0, "animation4", false);
                    this.spineLock.addAnimation(0, "animation1", true);
                }
            }
        }else {
            if(isInit) {
                this.spineLock.setAnimation(0, "animation3", false);
            }else {
                if(this.isOpen) {
                    SlotsFacade.soundMgr.playEffect("map_lock");
                    this.spineLock.setAnimation(0, "animation2", false);
                    this.spineLock.addAnimation(0, "animation3", false);
                }
            }
        }
        this.isOpen = boo;
    },

    /**
     * 设置水滴数量
     * @param cnt
     * @param playAni 是否播放动画
     */
     setCnt(cnt, playAni) {
        this.label.string = Global.FormatNumToComma(cnt);
        if(playAni) {
            this.spineArrive.node.active = true;
            this.spineArrive.setAnimation(0, "animation", false);
            this.spineArrive.setCompleteListener(()=>{
                this.spineArrive.setCompleteListener(null);
                this.spineArrive.node.active = false;
            });
        }
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     */
    async collectEnergy(globalPosArr) {
        SlotsFacade.soundMgr.playEffect("bonus_fly");
        let endPos = this.icon.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.traceParticle.node);
            lz.parent = this.node;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();
            promiseArr.push(new Promise(res=>{
                cc.tween(lz)
                    .to(0.5, {x:endPos.x, y:endPos.y})
                    .call(()=> {
                        lz.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        await Promise.all(promiseArr);
        this.setCnt(SlotsFacade.dm.energyData.gemCnt, true);
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    }
});
