cc.Class({
    extends: cc.Component,

    properties: {
        labelTemplate:cc.Label,
        jpParticleArr:[cc.Node],
        spineCenter:sp.Skeleton,
        spineBottom:sp.Skeleton,
        spineMultiple:sp.Skeleton,
        _cbHandler:null
    },

    onLoad() {
        this.labelTemplate.node.active = false;
        this.spineCenter.node.active = false;
        this.spineMultiple.node.active = false;
    },

    async enterBonus(cbHandler) {
        this._cbHandler = cbHandler;

        await this.assignmentJp();

        // 金币归结
        await this.settlementCoin();
        SlotsFacade.slots.resetReelBonusAni();
        if(cbHandler) {
            cbHandler(SlotsFacade.dm.getSpinData().bonusInfo.winCoin);
        }
    },

    /**
     * 给jackpot symbol赋值
     */
    async assignmentJp() {
        let bonusInfo = SlotsFacade.dm.getSpinData().bonusInfo;
        let jpItems = [];
        for(let i of bonusInfo.items) {
            if(i.jackpot) {
                jpItems.push(i);
            }
        }
        if(jpItems.length < 1) {
            return;
        }

        // 播放jp动画
        for(let item of jpItems) {
            SlotsFacade.prizePool.playWinAni(item.jackpot.id-1);
        }
        SlotsFacade.soundMgr.playEffect("green_dia_hit");
        await SlotsFacade.delayTime(1);

        // 飞行粒子
        for(let item of jpItems) {
            let pNode = cc.instantiate(this.jpParticleArr[item.jackpot.id-1]);
            pNode.active = true;
            pNode.parent = this.node;
            let startPos = SlotsFacade.prizePool.getJpGlobalPos(item.jackpot.id-1);
            startPos = this.node.convertToNodeSpaceAR(startPos);
            let symbol = SlotsFacade.slots.GetSymbolByIdx(item.idx);
            let endPos = SlotsFacade.slots.getIdxGlobalPos(item.idx);
            endPos = this.node.convertToNodeSpaceAR(endPos);
            pNode.position = startPos;
            cc.tween(pNode)
                .to(0.4, {x:endPos.x, y:endPos.y})
                .call(()=>{
                    pNode.removeFromParent(true);
                    SlotsFacade.soundMgr.playEffect("diamond_text_rotate");
                    symbol.showJpSymbolCoin(item.jackpot.value);
                })
                .start();
        }
        await SlotsFacade.delayTime(2.2);
    },

    /**
     * 结算金币
     */
    async settlementCoin() {
        // 初始化中间文本
        let centerPos = SlotsFacade.mainPanel.slots.convertToWorldSpaceAR(cc.v2(0,0));
        centerPos = this.node.convertToNodeSpaceAR(centerPos);
        let centerLabel = cc.instantiate(this.labelTemplate.node).getComponent(cc.Label);
        centerLabel.node.parent = this.node;
        centerLabel.node.active = true;
        centerLabel.string = "";
        centerLabel.node.position = centerPos;
        this.spineCenter.node.position = centerPos;
        this.spineCenter.node.active = true;

        // 排序是bonus symbol
        let bonusInfo = SlotsFacade.dm.getSpinData().bonusInfo;
        let items = bonusInfo.items.concat();
        items.sort((a,b)=>{
            let aIdxInfo = SlotsFacade.slots.transferIdx(a.idx);
            let bIdxInfo = SlotsFacade.slots.transferIdx(b.idx);
            if(aIdxInfo.col > bIdxInfo.col) {
                return 1;
            }else if(aIdxInfo.col < bIdxInfo.col) {
                return -1;
            }else {
                return aIdxInfo.row - bIdxInfo.row;
            }
        });

        // 移动金币
        let sum = 0;
        for(let i=0; i<items.length; i++) {
            let val = items[i].coin || items[i].jackpot.value;
            let label = cc.instantiate(this.labelTemplate.node).getComponent(cc.Label);
            label.node.active = true;
            label.node.parent = this.node;
            label.node.position = this.node.convertToNodeSpaceAR(SlotsFacade.slots.getIdxGlobalPos(items[i].idx));
            label.string = Global.convertNumToShort(val);
            SlotsFacade.soundMgr.playEffect(["diamond_collect1", "diamond_collect2", "diamond_collect3"][Math.floor(Math.random()*3)]);
            cc.tween(label.node)
                .to(0.6, {x:centerPos.x, y:centerPos.y}, {easing:"cubicIn"})
                .call(()=>{
                    label.node.removeFromParent(true)
                    this.spineCenter.setAnimation(0, "animation1", false);
                })
                .start();
            await SlotsFacade.delayTime(0.6);
            // centerLabel.string = Global.FormatNumToComma(sum);
            cc.tween(centerLabel.node)
                .to(0.3, {scale:centerLabel.node.scale*(1+0.2)}, {easing:"backOut"})
                .start();
            await new Promise(res=>{
                Global.doRoallNumEff(centerLabel, sum, sum+val, 1, res, null,0,true)
            })
            sum += val;
        }
        await SlotsFacade.delayTime(0.5);

        // 乘以倍数
        let freeInfo = SlotsFacade.dm.getSpinData().storeInfo.freeInfo;
        if(freeInfo) {
            let multBonus = freeInfo.multBonus;
            if(multBonus) {
                // 播放倍数动画
                this.spineMultiple.node.active = true;
                this.spineMultiple.node.position = cc.v2(0, 0);
                this.spineMultiple.setAnimation(0, `animation${multBonus}_1`, false);
                this.spineMultiple.addAnimation(0, `animation${multBonus}`, false, 0.35)
                this.spineMultiple.setCompleteListener(()=>{
                    this.spineMultiple.setCompleteListener(null);
                })
                SlotsFacade.soundMgr.playEffect("multi_collect4");
                // 移动倍数
                cc.tween(this.spineMultiple.node)
                    .to(0.9, {x:centerPos.x, y:centerPos.y})
                    .call(()=>{
                        this.spineMultiple.node.active = false;
                    })
                    .start();
                await SlotsFacade.delayTime(0.8);
                // 爆炸特效
                this.spineCenter.setAnimation(0, "animation2", false);
                this.spineCenter.setCompleteListener(()=>{
                    this.spineCenter.setCompleteListener(null);
                    this.spineCenter.node.active = false;
                })
                // 设置金币
                cc.tween(centerLabel.node)
                    .to(0.3, {scale:centerLabel.node.scale * (1 + multBonus/10)}, {easing:"backOut"})
                    .start();
                await new Promise(res=>{
                    Global.doRoallNumEff(centerLabel, sum, sum*multBonus, 1, res, null,0,true)
                })
                sum *= multBonus;
            }
        }

        // 结算金币
        let bottomLabel = cc.find("winBg/lbl_winNum_nor", SlotsFacade.bottomCmp.node);
        let bottomPos = bottomLabel.convertToWorldSpaceAR(cc.v2(0,0));
        bottomPos = this.node.convertToNodeSpaceAR(bottomPos);
        SlotsFacade.soundMgr.playEffect("diamond_collectall");
        cc.tween(centerLabel.node)
            .to(1, {x:bottomPos.x, y:bottomPos.y}, {easing:"cubicIn"})
            .call(()=>{
                centerLabel.node.removeFromParent(true);
                this.spineBottom.node.active = true;
                this.spineBottom.node.position = bottomPos;
                this.spineBottom.setAnimation(0, "animation", false);
                this.spineBottom.setCompleteListener(()=>{
                    this.spineBottom.setCompleteListener(null);
                    this.spineBottom.node.active = false;
                })
            })
            .start();
        await SlotsFacade.delayTime(1);
        let nWin = bonusInfo.winCoin;
        let nTotal = nWin;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin() - cc.vv.gameData.GetGameWin() + nWin;
        }
        bottomLabel.active = true;

        await new Promise(res=>{
            Global.doRoallNumEff(bottomLabel, nTotal-nWin, nTotal, 1, res, null,0,true)
        })
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
    }
});
