/**
 * 浪漫女王卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    /**
     * 显示免费游戏加速效果
     * 加速框的显示
     * @override
     * @constructor
     */
    ShowAntiEffect(bShow,name) {
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    if(this._stopRightNow){
                        cc.find("node_anti",this.node).active = false;
                        cc.find("dark_bg",this.node).active = false;
                        cc.vv.AudioManager.stopEffectByName(info.antSound);
                        this.node.scale = 1;
                        this.processReelBonusAni();
                    }else {
                        cc.tween(this.node)
                            .to(0.3, {scale:1})
                            .call(()=>{
                                this.node.zIndex = this.GetReelIdx();
                                cc.find("node_anti",this.node).active = false;
                                cc.find("dark_bg",this.node).active = false;
                                this.processReelBonusAni();
                            })
                            .start();
                    }
                }
            }
        }else{
            cc.find("node_anti",this.node).active = true;
            cc.find("node_bonus",this.node).active = true;
            cc.find("dark_bg",this.node).active = true;
            this.node.zIndex = 1000;
            cc.tween(this.node)
                .to(0.3, {scale:1.2})
                .start();
        }
    },

    showBonusAni(boo) {
        let bonusAni = cc.find("node_bonus", this.node);
        bonusAni.active = boo;
    },

    processReelBonusAni() {
        if(!SlotsFacade.dm.getSpinData() || !SlotsFacade.dm.getSpinData().storeInfo) {
            return;
        }
        if(SlotsFacade.dm.getSpinData().storeInfo.state > 0) {
            return;
        }
        if(SlotsFacade.dm.GetTotalFree() > 0) {
            return;
        }
        let reelCards = SlotsFacade.dm.getReelCards(this.GetReelIdx());
        let canBonusCards = [3, 301, 302];
        let hasBonusSymbol = false;
        for(let c of reelCards) {
            if(canBonusCards.includes(c)) {
                hasBonusSymbol = true;
                break;
            }
        }
        if(hasBonusSymbol) {
            this.showBonusAni(true);
        }else {
            this.showBonusAni(false);
        }
    }
});
