// jp相关配置
let JpCfg =  {
    "0":{
        nodeName:"prizePool_Mini",  // 节点名称
        lockAni:"animation5_1",     // 枷锁动画
        unlockAni:"animation5_2",   // 解锁动画
        idleAni:"animation5",       // idle动画
        winAni:"animation5",        // 中奖动画
        iconIndex:0,    // 提示中的图标下标
        weight:0,       // 权重
    },
    "1":{
        nodeName:"prizePool_Minor",
        lockAni:"animation4_1",
        unlockAni:"animation4",
        idleAni:"animation4",
        winAni:"animation4",
        iconIndex:1,
        weight:1,
    },
    "2":{
        nodeName:"prizePool_Major",
        lockAni:"animation3_1",
        unlockAni:"animation3",
        idleAni:"animation3",
        winAni:"animation3",
        iconIndex:2,
        weight:2,
    },
    "3":{
        nodeName:"prizePool_Maxi",
        lockAni:"animation2_1",
        unlockAni:"animation2",
        idleAni:"animation2",
        winAni:"animation2",
        iconIndex:3,
        weight:3,
    },
    "4":{
        nodeName:"prizePool_Grand",
        lockAni:"animation1_1",
        unlockAni:"animation1",
        idleAni:"animation1",
        winAni:"animation1",
        iconIndex:4,
        weight:4,
    }
};


cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {

    },

    start () {
        this._super()
        this.scheduleOnce(()=>{
            if(this.node.y > cc.winSize.height / 2){
                this.node.y = cc.winSize.height / 2;
            }
        },0);
    },

    /**
     * @override
     * @param {*} node
     * @param {*} bLock
     * @param {*} unLockBet
     * @param {*} poolType
     * @param {*} bInit
     */
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        if(!JpCfg[poolType+""]) {
            return;
        }
        let param = {
            poolIdx:poolType,
            val:bLock
        };
        this.processTips(param);
    },

    processTips(data){
        this.showJackPotTips(data.poolIdx, data.val);
        let aniCfg = JpCfg[data.poolIdx+""];
        let jpNodeName = aniCfg.nodeName;
        if(jpNodeName){
            let safeNode = cc.find('Canvas/safe_node')
            let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
            if(jpNode){
                let targetJpNode = cc.find(jpNodeName, jpNode.node.parent)
                if(targetJpNode){
                    let lockSp = targetJpNode.getChildByName('spine_lock').getComponent(sp.Skeleton);
                    let bgImg = targetJpNode.getChildByName('bg').getComponent("ImgSwitchCmp");
                    let titleImg = targetJpNode.getChildByName('title').getComponent("ImgSwitchCmp");
                    if(data.val){
                        //锁
                        targetJpNode.isLock = true;
                        SlotsFacade.soundMgr.stopEffectByName("jp_lock");
                        SlotsFacade.soundMgr.playEffect("jp_lock");
                        lockSp.node.active = true;
                        lockSp.setAnimation(0, aniCfg.lockAni,false);
                        lockSp.setCompleteListener(()=>{
                            lockSp.setCompleteListener(null);
                            lockSp.node.active = false;
                        })
                        this.scheduleOnce(()=>{
                            bgImg.setIndex(1);
                            titleImg.setIndex(1);
                            targetJpNode.getChildByName("lbl_num").color = cc.Color.GRAY;
                            targetJpNode.getChildByName("spine_idle").active = false;
                        }, 0.4);
                    }else{
                        // 解锁
                        targetJpNode.isLock = false;
                        SlotsFacade.soundMgr.stopEffectByName("jp_unlock");
                        SlotsFacade.soundMgr.playEffect("jp_unlock");
                        lockSp.node.active = true;
                        lockSp.setAnimation(0, aniCfg.unlockAni,false);
                        lockSp.setCompleteListener(()=>{
                            lockSp.setCompleteListener(null);
                            lockSp.node.active = false;
                        })
                        this.scheduleOnce(()=>{
                            bgImg.setIndex(0);
                            titleImg.setIndex(0);
                            targetJpNode.getChildByName("lbl_num").color = cc.Color.WHITE;
                            let spineIdle = targetJpNode.getChildByName("spine_idle").getComponent(sp.Skeleton);
                            spineIdle.node.active = true;
                            spineIdle.setAnimation(0, aniCfg.idleAni, true);
                        }, 0.4);
                    }
                }
            }
        }
    },

    showJackPotTips(jpId,isLock){
        let weight = JpCfg[jpId+""].weight;
        if(isLock){
            if(this._nowJpLockWeight < weight){
                return;
            }
            this._nowJpLockWeight = weight;
        }else{
            if(this._nowJpUnlockWeight > weight){
                return;
            }
            this._nowJpUnlockWeight = weight;
        }
        let aniCfg = JpCfg[jpId+""];
        let jpNodeName = aniCfg.nodeName;
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        let targetJpNode = cc.find(jpNodeName, jpNode.node.parent)
        if(targetJpNode){
            let tips_to_unclok = targetJpNode.parent.getChildByName("tips_to_unclok");
            tips_to_unclok.stopAllActions();
            tips_to_unclok.active = false;
            tips_to_unclok.getChildByName("icon").getComponent("ImgSwitchCmp").setIndex(aniCfg.iconIndex);
            tips_to_unclok.x = targetJpNode.x;
            tips_to_unclok.y = targetJpNode.y;
            let tips_uncloked = targetJpNode.parent.getChildByName("tips_uncloked");
            tips_uncloked.stopAllActions();
            tips_uncloked.active = false;
            tips_uncloked.getChildByName("icon").getComponent("ImgSwitchCmp").setIndex(aniCfg.iconIndex);
            tips_uncloked.x = targetJpNode.x;
            tips_uncloked.y = targetJpNode.y;

            if(isLock) {
                this._nowJpUnlockWeight = this._nowJpLockWeight-1;
                tips_to_unclok.scale = 0;
                tips_to_unclok.active = true;
                cc.tween(tips_to_unclok)
                    .to(0.4, {scale:1}, {easing:"backOut"})
                    .delay(2)
                    .to(0.2, {scale:0})
                    .call(()=>{
                        tips_to_unclok.active = false;
                    })
                    .start();
            }else {
                this._nowJpLockWeight = this._nowJpUnlockWeight+1;
                tips_uncloked.scale = 0;
                tips_uncloked.active = true;
                cc.tween(tips_uncloked)
                    .to(0.4, {scale:1}, {easing:"backOut"})
                    .delay(2)
                    .to(0.2, {scale:0})
                    .call(()=>{
                        tips_uncloked.active = false;
                    })
                    .start();
            }
        }
    },

    /**
     * 播放中奖jp 动画
     * @param jpType
     */
     playWinAni(jpType) {
        let aniCfg = JpCfg[jpType.toString()];
        let spine = cc.find(`${aniCfg.nodeName}/spine_win`, this.node).getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, aniCfg.winAni, false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        })
    },

    /**
     * 获取jp全局坐标
     * @param jpType
     */
    getJpGlobalPos(jpType) {
        let aniCfg = JpCfg[jpType.toString()];
        let jpNode = cc.find(`${aniCfg.nodeName}/spine_win`, this.node);
        return jpNode.convertToWorldSpaceAR(cc.v2(0, 0));
    }
});
