
/**
 * 浪漫女王slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        mask:cc.Node,
    },

    onLoad() {
        this._super();
        this.mask = this.node.getChildByName("mask");
    },

    //重写
    StartMove: function () {
        this._super()
        SlotsFacade.flowCtrl.startMove();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    //重写
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx -1;
        let col = idx % this._col
        let row = this._row - Math.floor(idx/this._col) -1;
        return {col:col, row:row};
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 设置symbol数据
     * @param cards
     * @constructor
     */
    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {idx:i+1};
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        let spinData = SlotsFacade.dm.getSpinData();
        // 设置bonus数据
        if(spinData.bonusInfo && spinData.bonusInfo.items.length>0) {
            for(let i=0; i<spinData.bonusInfo.items.length; i++) {
                let bonusItem = spinData.bonusInfo.items[i];
                if(bonusItem.coin) {
                    let idxInfo = this.transferIdx(bonusItem.idx);
                    reelResults[idxInfo.col][idxInfo.row].data.coin = bonusItem.coin;
                }
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    /**
     * @override
     * @param cards
     * @constructor
     */
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            if(info.inNormal) {
                if(SlotsFacade.dm.getSpinData().storeInfo.state > 0) {
                    continue;
                }
                if(SlotsFacade.dm.GetTotalFree() > 0) {
                    continue;
                }
            }
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                if(reelCountOfID>0) {
                    haveCount +=  1;
                }
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true;
                    if(stateInfo.isScatter) {
                        stateInfo.symbolStopSound = `sc_land${reelCountOfID}`;
                    }
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    /**
     * @override
     * @constructor
     */
    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        // 标记wild 合并情况
        let reels = this._reels;
        let reelsLen = reels.length;
        for(let i=0; i<reelsLen; i++) {
            let r = reels[i];
            let flags  = [false, false, false, false];
            for(let j=0; j<4; j++) {
                let s = r._symbols[j];
                let idx = (3-j)*reelsLen + (i+1);
                if(s.GetShowId() == 1 && allWinIdx[idx]) {
                    flags[j] = true;
                }
            }
            if(flags[0] && flags[1] && flags[2] && flags[3]) {
                r._symbols[0].wildAniCount = 4;
                r._symbols[1].wildAniCount = 0;
                r._symbols[2].wildAniCount = 0;
                r._symbols[3].wildAniCount = 0;
            }else if(flags[0] && flags[1] && flags[2]) {
                r._symbols[0].wildAniCount = 3;
                r._symbols[1].wildAniCount = 0;
                r._symbols[2].wildAniCount = 0;
            }else if(flags[0] && flags[1]) {
                r._symbols[0].wildAniCount = 2;
                r._symbols[1].wildAniCount = 0;
            }else if(flags[1] && flags[2] && flags[3]) {
                r._symbols[1].wildAniCount = 3;
                r._symbols[2].wildAniCount = 0;
                r._symbols[3].wildAniCount = 0;
            }else if(flags[1] && flags[2]) {
                r._symbols[1].wildAniCount = 2;
                r._symbols[2].wildAniCount = 0;
            }else if(flags[2] && flags[3]) {
                r._symbols[2].wildAniCount = 2;
                r._symbols[3].wildAniCount = 0;
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }


    },

    /**
     * 显示遮罩
     */
    showMask() {
        this.mask.active = true;
        this.mask.opacity = 0;
        cc.tween(this.mask)
            .to(0.2, {opacity:140})
            .start();
    },

    /**
     * 隐藏遮罩
     */
    hideMask() {
        if(!this.mask.active) {
            return;
        }
        cc.tween(this.mask)
            .to(0.8, {opacity:0})
            .call(res=>{
                this.mask.active = false;
            })
            .start();
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 摇晃卷轴
     * @returns {Promise<void>}
     */
    async shakeReels(time, offset) {
        SlotsFacade.soundMgr.playEffect("sym_shake");
        time = time || 1;
        offset = offset || 2;
        for(let reel of this._reels) {
            Global.shakeNode(reel.node, offset, time);
        }
        await SlotsFacade.delayTime(time);
    },

    /**
     * 重置 bonus reel ani状态
     */
    resetReelBonusAni() {
        for(let reel of this._reels) {
            reel.showBonusAni(false);
        }
    },

    /**
     * 更新所有symbol
     */
    updateAllSymbol() {
        SlotsFacade.dm.updateRandomSymbols();
        for(let reel of this._reels) {
            let symbols = reel._symbols;
            for(let s of symbols) {
                s.StartMove();
                s.ShowRandomSymbol();
            }
        }
    },
});
