/**
 * 收集游戏
 */
cc.Class({
    extends: cc.Component,

    properties: {
        bg:cc.Node,
        panel:cc.Node,
        // 列表相关
        scrollView:cc.ScrollView,
        item_template:cc.Node,
        // 免费次数设置相关
        free_cnt_node:cc.Node,
        free_cnt_btn_minus:cc.Button,  // 减按钮
        free_cnt_btn_plus:cc.Button,   // 加按钮
        free_cnt_label_freeCnt:cc.Label, // 免费次数文本
        free_cnt_label_cost:cc.Label,  // 免费次数消耗的水滴

        resetBtn:cc.Button, // 重置按钮
        startBtn:cc.Button, // 开始按钮
        startToCostWaterDropLabel:cc.Label, // 开始免费需要的水滴数量
        closeBtn:cc.Button, // 关闭按钮
        totalWaterDropLabel:cc.Label,       // 总共拥有的水滴数量

        _storeListCfg:[],    // store 列表配置
        _storeItemList:[],   // store item 列表
        _currSelectItem:null, // 当前选中的 store item
        _cbHandler:null,
        _data:null
    },

    onLoad() {
        this.panel.active = false;
        this.item_template.active = false;
        this.closeBtn.node.on("click", ()=>{this.close(true)}, this);
        this.resetBtn.node.on("click", ()=>{this._reset()}, this);
        this.startBtn.node.on("click", ()=>{this._startGame()}, this);

        this.free_cnt_btn_minus.node.on("click", ()=>{this._onFreeCntChange(-1)}, this);
        this.free_cnt_btn_plus.node.on("click", ()=>{this._onFreeCntChange(1)}, this);
    },

    start() {
        this._initList();
    },

    _initList() {
        let storeItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        this._storeListCfg = [
            {
                mergeType:storeItemType.stickyWild,
                titleIndex:[0],
                types:[{type:storeItemType.stickyWild, selectorType:1, info:[1,2,3,4,5]}],
                data: {},
            },
            {
                mergeType:storeItemType.randWild,
                titleIndex:[1],
                types:[{type:storeItemType.randWild, selectorType:1, info:[1,2,3,4,5]}],
                data: {},
            },
            {
                mergeType:storeItemType.roamingWilds,
                titleIndex:[2],
                types:[{type:storeItemType.roamingWilds, selectorType:5, info:[[3,4,5], [2,3,4,5], [1,2,3,4,5]]}],
                data: {},
            },
            {
                mergeType:storeItemType.removeSymbol,
                titleIndex:[3],
                types:[{type:storeItemType.removeSymbol, selectorType:2, info:[[13], [12,13], [11,12,13], [10,11,12,13], [9,10,11,12,13]]}],
                data: {},
            },
            {
                mergeType:storeItemType.extraBonus,
                titleIndex:[4],
                types:[{type:storeItemType.extraBonus, selectorType:3, info:[[3], [3,301], [3,301,302]]}],
                data: {},
            },
            {
                mergeType:storeItemType.multWild,
                titleIndex:[5],
                types:[{type:storeItemType.multWild, selectorType:4, info:[2,3,4]}],
                data: {},
            },
            {
                mergeType:storeItemType.stickyWildAndRemoveSymbol,
                titleIndex:[6,7],
                types:[
                    {type:storeItemType.stickyWild, selectorType:1, info:[1,2,3,4,5]},
                    {type:storeItemType.removeSymbol, selectorType:2, info:[[13], [12,13], [11,12,13], [10,11,12,13], [9,10,11,12,13]]},
                ],
                data: {},
            },
            {
                mergeType:storeItemType.randomWildAndRemoveSymbol,
                titleIndex:[8,7],
                types:[
                    {type:storeItemType.randWild, selectorType:1, info:[1,2,3,4,5]},
                    {type:storeItemType.removeSymbol, selectorType:2, info:[[13], [12,13], [11,12,13], [10,11,12,13], [9,10,11,12,13]]},
                ],
                data: {},
            },
            {
                mergeType:storeItemType.roamingWildAndRemoveSymbol,
                titleIndex:[9,7],
                types:[
                    {type:storeItemType.roamingWilds, selectorType:5, info:[[3,4,5], [2,3,4,5], [1,2,3,4,5]]},
                    {type:storeItemType.removeSymbol, selectorType:2, info:[[13], [12,13], [11,12,13], [10,11,12,13], [9,10,11,12,13]]},
                ],
                data: {},
            },
            {
                mergeType:storeItemType.extraBonusAndMultBonus,
                titleIndex:[10,11],
                types:[
                    {type:storeItemType.extraBonus, selectorType:3, info:[[3], [3,301], [3,301,302]]},
                    {type:storeItemType.multWild, selectorType:4, info:[2,3,4]},
                ],
                data: {},
            }
        ];
        // 填充 _storeListCfg 的 mults数据
        for(let i=0; i<this._storeListCfg.length; i++) {
            let item = this._storeListCfg[i];
            let itemCfg = this._getStoreCfgItem(item.mergeType);
            for(let j=0; j<itemCfg.info.length; j++) {
                if(itemCfg.info[j] instanceof Array) {
                    if(itemCfg.type >= 8) {
                        item.data[itemCfg.info[j].join("-")] = itemCfg.mults[j];
                    }else {
                        item.data[itemCfg.info[j].join(",")] = itemCfg.mults[j];
                    }
                }else {
                    item.data[itemCfg.info[j].toString()] = itemCfg.mults[j];
                }
            }
        }
        // 初始化列表
        for(let i=0; i<this._storeListCfg.length; i++) {
            let item = cc.instantiate(this.item_template);
            item.active = true;
            item.parent = this.scrollView.content;
            let itemCmp = item.addComponent("RomanticPrincess_StoreItem");
            itemCmp.id = i;
            itemCmp.init(this._storeListCfg[i], this._onStoreItemChange.bind(this));
            this._storeItemList.push(itemCmp);
        }
    },

    _getStoreCfgItem(storeType) {
        let storeConfig = SlotsFacade.dm.getDeskInfo().storeConfig;
        for(let i=0; i<storeConfig.items.length; i++) {
            let item = storeConfig.items[i];
            if(item.type == storeType) {
                return item;
            }
        }
        return null;
    },

    _resetData() {
        this._data = {
            freeCnt:3,  // 免费次数
            freeCost:0, // 免费次数消耗的水滴
            storeItemCost:0, // storeItem消耗的水滴
        }
    },

    /**
     * 修改免费次数
     * @param val
     * @private
     */
    _onFreeCntChange(val) {
        SlotsFacade.soundMgr.playEffect("click");
        this._data.freeCnt += val;
        if(this._data.freeCnt < 3) {
            this._data.freeCnt = 3;
        }
        this.free_cnt_btn_minus.interactable = this._data.freeCnt > 3;
        this._data.freeCost = this._data.freeCnt * SlotsFacade.dm.getDeskInfo().storeConfig.freeBaseCoin;

        if(this._currSelectItem) {
            this._data.storeItemCost = this._data.freeCnt * this._currSelectItem.getMultiple();
            this._currSelectItem.setCost(this._data.storeItemCost);
        }
        this._updateTotalCost();
        this._updateFreeCnt();
    },

    /**
     * store item 事件处理
     * @param data
     * @private
     */
    _onStoreItemChange(data) {
        if(data.evt == "open") {
            SlotsFacade.soundMgr.playEffect("click");
            if(this._currSelectItem) {
                this._currSelectItem.close();
            }
            this._currSelectItem = data.target;

        }else if(data.evt == "change") {

        }
        let storeItem = data.target;
        this._data.storeItemCost = this._data.freeCnt * storeItem.getMultiple();
        storeItem.setCost(this._data.storeItemCost);
        this._updateTotalCost();
    },

    /**
     * 更新免费次数
     */
    _updateFreeCnt() {
        this.free_cnt_label_freeCnt.string = this._data.freeCnt.toString();
        this.free_cnt_label_cost.string = Global.FormatNumToComma(this._data.freeCost);
    },

    /**
     * 更新总消耗
     * @private
     */
    _updateTotalCost() {
        let total = this._data.freeCost + this._data.storeItemCost;
        this.startToCostWaterDropLabel.string = Global.FormatNumToComma(total.toString());
        if(SlotsFacade.dm.energyData.gemCnt >= total) {
            this.startBtn.interactable = true;
        }else {
            this.startBtn.interactable = false;
        }
    },

    /**
     * 重置
     */
    _reset() {
        this.startBtn.interactable = true;
        this.resetBtn.interactable = true;
        this.closeBtn.interactable = true;
        let storeInfo = SlotsFacade.dm.energyData;
        if(this._currSelectItem) {
            this._currSelectItem.close();
        }
        this._currSelectItem = null;
        this.totalWaterDropLabel.string = Global.FormatNumToComma(storeInfo.gemCnt);
        this._resetData();
        this._onFreeCntChange(0);
        for(let item of this._storeItemList) {
            item.close();
        }
        this.scrollView.scrollToTop();
    },

    /**
     * 开始游戏
     */
    _startGame() {
        let param = {
            rtype:1,
            choiceInfo:{
                freeCnt:this._data.freeCnt,
            }
        }
        if(this._currSelectItem) {
            let mergeType = this._currSelectItem.storeItemCfg.mergeType;
            let itemCfg = this._getStoreCfgItem(mergeType);
            let idx = itemCfg.mults.indexOf(this._currSelectItem.getMultiple()) + 1;
            param.choiceInfo.type = mergeType;
            param.choiceInfo.idx = idx;
        }
        this.startBtn.interactable = false;
        this.resetBtn.interactable = false;
        this.closeBtn.interactable = false;
        SlotsFacade.dm.reqSubGame(param);
    },

    /**
     * 收到开始消息
     * @param msg
     */
    async onMsg(msg) {
        if(msg.data.rtype != 1) {
            return;
        }
        let storeInfo = msg.data.storeInfo;
        SlotsFacade.dm.energyData = storeInfo;
        SlotsFacade.dm.SetFreeTime(storeInfo.freeInfo.freeCnt);
        SlotsFacade.dm.SetTotalFree(storeInfo.freeInfo.freeCnt);
        SlotsFacade.mainPanel.showSceneTransition(1);
        SlotsFacade.bottomCmp.DoHideWinAction();
        this.totalWaterDropLabel.string = Global.FormatNumToComma(storeInfo.gemCnt);
        SlotsFacade.collect.setCnt(SlotsFacade.dm.energyData.gemCnt);
        await SlotsFacade.delayTime(3);
        this.close();
        await SlotsFacade.flowCtrl.enterFreeGame();
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 打开商店
     * @param cb
     */
    open(cb) {
        SlotsFacade.soundMgr.playEffect("store_open");
        this.bg.active = true;
        this._cbHandler = cb;
        this.scheduleOnce(()=>{
            this.panel.active = true;
            this._reset();
            this.panel.scale = 0;
            cc.tween(this.panel)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .start();
            for(let i=0; i<this._storeItemList.length; i++) {
                let item = this._storeItemList[i];
                item.node.scale = 0;
                cc.tween(item.node)
                    .delay(0.1*i)
                    .to(0.3, {scale:1}, {easing:"backOut"})
                    .start();
            }
        })
    },

    /**
     * 退出商店
     */
    async close(isAni) {
        SlotsFacade.soundMgr.playEffect("store_close");
        if(isAni) {
            cc.tween(this.panel)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .start();
            await SlotsFacade.delayTime(0.5);
        }
        this.bg.active = false;
        this.panel.active = false;
        if(this._cbHandler) {
            this._cbHandler();
        }
    }
});
